// step 0: dot_general → mul → reduce_sum → mul → add → sqrt → reshape → broadcast_in_dim → div → broadcast_in_dim → mul
// { lambda %0:f32[2048,512] %1:f32[512,64] %2:f32[64]. let
//     %3:f32[2048,64] = dot_general[dimension_numbers=(((1,), (0,)), ((), ())) accum_dtype=f32 output_dtype=f32] %0 %1
//     %4:f32[2048,64] = mul %3 %3
//     %5:f32[2048] = reduce_sum[axes=(1,) accum_dtype=f32] %4
//     %6:f32[] = full[dtype=f32 fill_value=0.015625 shape=()]
//     %7:f32[2048] = broadcast_in_dim[broadcast_dimensions=() shape=(2048,)] %6
//     %8:f32[2048] = mul %5 %7
//     %9:f32[] = full[dtype=f32 fill_value=1e-6 shape=()]
//     %10:f32[2048] = broadcast_in_dim[broadcast_dimensions=() shape=(2048,)] %9
//     %11:f32[2048] = add %8 %10
//     %12:f32[2048] = sqrt %11
//     %13:f32[2048,1] = reshape[new_sizes=(2048, 1)] %12
//     %14:f32[2048,64] = broadcast_in_dim[broadcast_dimensions=(0, 1) shape=(2048, 64)] %13
//     %15:f32[2048,64] = div %3 %14
//     %16:f32[2048,64] = broadcast_in_dim[broadcast_dimensions=(1,) shape=(2048, 64)] %2
//     %17:f32[2048,64] = mul %15 %16
//   in (%17) }

template <typename T, typename I>
inline T fusion_f02e5b4d5783695b_load2(device const T *p, I i) {
    return p[i];
}

struct fusion_f02e5b4d5783695b_staging {
    threadgroup float *staged;
    // Each lane's elements of the accumulators (two of each 8x8
    // matrix), rounded to the dot's dtype, at their place in the
    // tile; the columns past the rows' none.
    template <uint FM, uint FN>
    void tile(thread simdgroup_matrix<float, 8, 8> (&c)[FM][FN],
              ulong m0,
              ulong n0,
              uint sy,
              uint sx,
              uint flat,
              uint lane) {
        const uint fr = frag_row(lane), fc = frag_col(lane);
        UNROLL for (uint i = 0; i < FM; ++i) {
            UNROLL for (uint j = 0; j < FN; ++j) {
                const vec<float, 2> e = frag(c[i][j]);
                const uint r = (sy * FM + i) * 8 + fr, col = (sx * FN + j) * 8 + fc;
                if (col < 64u) {
                    staged[r * 64u + col] = float(e[0]);
                }
                if (col + 1 < 64u) {
                    staged[r * 64u + col + 1] = float(e[1]);
                }
            }
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
};

kernel void fusion_f02e5b4d5783695b(device const float *in0 [[buffer(0)]],
                                    device const float *in1 [[buffer(1)]],
                                    device const float *in2 [[buffer(2)]],
                                    device float *out [[buffer(3)]],
                                    constant ulong *p [[buffer(4)]],
                                    uint3 group [[threadgroup_position_in_grid]],
                                    uint3 tid [[thread_position_in_threadgroup]],
                                    uint sg [[simdgroup_index_in_threadgroup]],
                                    uint lane [[thread_index_in_simdgroup]]) {
    threadgroup float lt[SG_LT(64, SG_BK, float, float)], rt[SG_RT(SG_BK, 64, float)];
    threadgroup float staged[64 * 64];
    matmul_sg_impl<float, float, float, 64, 64, SG_BK, float,
                   fusion_f02e5b4d5783695b_staging, false, false, true>(
        in0, in1, (device float *)nullptr, p,
        lt, rt,
        group, tid.y * 16 + tid.x, sg, lane,
        fusion_f02e5b4d5783695b_staging{staged});
    const ulong m0n = ulong(group.y) * 64 * 64;
    for (uint rr = sg; rr < 64u; rr += 8u) {
        uint row = group.y * 64u + rr, t = lane;
        if (row >= 2048u) {
            break;
        }
        float kept0[2];
        float acc0 = Add::template identity<float>();
        _Pragma("clang loop unroll(full)") for (uint e = 0; e < 2u; ++e) {
            uint c = t + e * 32u;
            uint j = row * 64u + c;
            float v0 = staged[(j) - m0n];
            float v1 = Mul::apply(v0, v0);
            acc0 = Add::apply(acc0, v1);
            kept0[e] = v0;
        }
        float r0 = simd_sum(acc0);
        // the same across the row: once a row
        float v2 = as_type<float>(uint(0x3c800000u)) /* 0.015625 */;
        float v3 = Mul::apply(r0, v2);
        float v4 = as_type<float>(uint(0x358637bdu)) /* 0.000001 */;
        float v5 = Add::apply(v3, v4);
        float v6 = Sqrt::apply(v5);
        _Pragma("clang loop unroll(full)") for (uint e = 0; e < 2u; ++e) {
            uint c = t + e * 32u;
            uint j = row * 64u + c;
            float v7 = Div::apply(kept0[e], v6);
            uint i8 = c;
            float v9 = fusion_f02e5b4d5783695b_load2(in2, i8);
            float v10 = Mul::apply(v7, v9);
            out[j] = v10;
        }
    }
}
